using System;using System.Linq;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEngine.InputSystem;
public static class BMInputInspect {public static object Run(){var p=SceneManager.GetActiveScene().GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));var pi=p.GetComponent<PlayerInput>();return new{scene=SceneManager.GetActiveScene().path,dirty=SceneManager.GetActiveScene().isDirty,Application.isPlaying,Application.runInBackground,Application.isFocused,Time.deltaTime,Time.time,active=p.activeInHierarchy,EditorApplication.isPaused,Time.timeScale,Time.frameCount,map=pi.currentActionMap?.name,pi.currentControlScheme,devices=pi.devices.Select(d=>new{d.name,d.enabled}).ToArray(),keyboard=Keyboard.current?.enabled,w=Keyboard.current?.wKey.isPressed,focus=EditorWindow.focusedWindow?.GetType().Name,background=InputSystem.settings.backgroundBehavior.ToString(),editorMode=InputSystem.settings.editorInputBehaviorInPlayMode.ToString(),actions=pi.actions.Select(a=>new{a.name,a.enabled,value=a.ReadValueAsObject()?.ToString()}).ToArray(),components=p.GetComponentsInChildren<MonoBehaviour>().Select(c=>new{type=c.GetType().Name,c.enabled,fields=c.GetType().GetFields(BindingFlags.Instance|BindingFlags.NonPublic).Where(f=>f.FieldType==typeof(Vector2)||f.FieldType==typeof(bool)).Select(f=>new{f.Name,value=f.GetValue(c)?.ToString()}).ToArray()}).ToArray()};}}
